"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[55662],{65717:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>r,contentTitle:()=>h,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var s=o(31085),n=o(71184);const i={sidebar_position:67,slug:"/bible/Psalms/Psalms_67",title:"Psalms 67",hide_table_of_contents:!0},h="Psalms",a={id:"bible/Psalms/Psalms 67",title:"Psalms 67",description:"Chapter 67",source:"@site/docs/bible/Psalms/Psalms 67.md",sourceDirName:"bible/Psalms",slug:"/bible/Psalms/Psalms_67",permalink:"/docs/bible/Psalms/Psalms_67",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Psalms/Psalms 67.md",tags:[],version:"current",sidebarPosition:67,frontMatter:{sidebar_position:67,slug:"/bible/Psalms/Psalms_67",title:"Psalms 67",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Psalms 66",permalink:"/docs/bible/Psalms/Psalms_66"},next:{title:"Psalms 68",permalink:"/docs/bible/Psalms/Psalms_68"}},r={},d=[{value:"Chapter 67",id:"chapter-67",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,n.R)(),...e.components},{BibleText:o}=t;return o||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.h1,{id:"psalms",children:"Psalms"}),"\n",(0,s.jsx)(t.h2,{id:"chapter-67",children:"Chapter 67"}),"\n",(0,s.jsx)(t.p,{children:"Exurgat Deus. The glorious establishment of the church of the New Testament, prefigured by the benefits bestowed on the people of Israel."}),"\n",(0,s.jsx)(o,{verse:1,children:"Unto the end, a psalm of a canticle for David himself."}),"\n",(0,s.jsx)(o,{verse:2,children:"Let God arise, and let his enemies be scattered: and let them that hate him flee from before his face."}),"\n",(0,s.jsx)(o,{verse:3,children:"As smoke vanisheth, so let them vanish away: as wax melteth before the fire, so let the wicked perish at the presence of God."}),"\n",(0,s.jsx)(o,{verse:4,children:"And let the just feast, and rejoice before God: and be delighted with gladness."}),"\n",(0,s.jsx)(o,{verse:5,children:"Sing ye to God, sing a psalm to his name, make a way for him who ascendeth upon the west: the Lord is his name. Rejoice ye before him: but the wicked shall be troubled at his presence,"}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Who ascendeth upon the west...Super occasum. St. Gregory understands it of Christ, who after his going down, like the sun, in the west, by his passion and death, ascended more glorious, and carried all before him. St. Jerome renders it, who ascendeth, or cometh up, through the deserts."})}),"\n",(0,s.jsx)(o,{verse:6,children:"Who is the father of orphans, and the judge of widows. God in his holy place:"}),"\n",(0,s.jsx)(o,{verse:7,children:"God who maketh men of one manner to dwell in a house: Who bringeth out them that were bound in strength; in like manner them that provoke, that dwell in sepulchres."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Of one manner...That is, agreeing in faith, unanimous in love, and following the same manner of discipline. It is verified in the servants of God, living together in his house, which is the church. 1 Tim.\nNote 2: 3.15.--Ibid. Them that were bound, etc...The power and mercy of God appears in his bringing out of their captivity those that were strongly bound in their sins: and in restoring to his grace those whose behaviour had been most provoking; and who by their evil habits were not only dead, but buried in their sepulchres."})}),"\n",(0,s.jsx)(o,{verse:8,children:"O God, when thou didst go forth in the sight of thy people, when thou didst pass through the desert:"}),"\n",(0,s.jsx)(o,{verse:9,children:"The earth was moved, and the heavens dropped at the presence of the God of Sina, at the presence of the God of Israel."}),"\n",(0,s.jsx)(o,{verse:10,children:"Thou shalt set aside for thy inheritance a free rain, O God: and it was weakened, but thou hast made it perfect."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: A free rain...the manna, which rained plentifully from heaven, in favour of God's inheritance, that is, of his people Israel: which was weakened indeed under a variety of afflictions, but was made perfect by God; that is, was still supported by divine providence, and brought on to the promised land. It agrees particularly to the church of Christ his true inheritance, which is plentifully watered with the free rain of heavenly grace; and through many infirmities, that is, crosses and tribulations, is made perfect, and fitted for eternal glory."})}),"\n",(0,s.jsx)(o,{verse:11,children:"In it shall thy animals dwell; in thy sweetness, O God, thou hast provided for the poor."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: In it, etc...That is, in this church, which is thy fold and thy inheritance, shall thy animals, thy sheep, dwell: where thou hast plentifully provided for them."})}),"\n",(0,s.jsx)(o,{verse:12,children:"The Lord shall give the word to them that preach good tidings with great power."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: To them that preach good tidings...Evangelizantibus. That is, to the preachers of the gospel; who receiving the word from the Lord, shall with great power and efficacy preach throughout the world the glad tidings of a Saviour, and of eternal salvation through him."})}),"\n",(0,s.jsx)(o,{verse:13,children:"The king of powers is of the beloved, of the beloved; and the beauty of the house shall divide spoils."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: The king of powers...That is, the mighty King, the Lord of hosts, is of the beloved, of the beloved; that is, is on the side of Christ, his most beloved son: and his beautiful house, viz., the church, in which God dwells forever, shall by her spiritual conquests divide the spoils of many nations. The Hebrew (as it now stands pointed) is thus rendered, The kings of armies have fled, they have fled, and she that dwells at home (or the beauty of the house) shall divide the spoils."})}),"\n",(0,s.jsx)(o,{verse:14,children:"If you sleep among the midst of lots, you shall be as the wings of a dove covered with silver, and the hinder parts of her back with the paleness of gold."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: If you sleep among the midst of lots (intermedios cleros, etc.)...Viz., in such dangers and persecutions, as if your enemies were casting lots for your goods and persons: or in the midst of the lots, (intermedios terminos, as St. Jerome renders it,) that is, upon the very bounds or borders of the dominions of your enemies: you shall be secure nevertheless under the divine protection; and shall be enabled to fly away, like a dove, with glittering wings and feathers shining like the palest and most precious gold; that is, with great increase of virtue, and glowing with the fervour of charity."})}),"\n",(0,s.jsx)(o,{verse:15,children:"When he that is in heaven appointeth kings over her, they shall be whited with snow in Selmon."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Kings over her...That is, pastors and rulers over his church, viz., the apostles and their successors. Then by their ministry shall men be made whiter than the snow which lies on the top of the high mountain Selmon."})}),"\n",(0,s.jsx)(o,{verse:16,children:"The mountain of God is a fat mountain. A curdled mountain, a fat mountain."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: The mountain of God...The church, which, Isa. 2.2, is called The mountain of the house of the Lord upon the top of mountains. It is here called a fat and a curdled mountain; that is to say, most fruitful, and enriched by the spiritual gifts and graces of the Holy Ghost."})}),"\n",(0,s.jsx)(o,{verse:17,children:"Why suspect, ye curdled mountains? A mountain in which God is well pleased to dwell: for there the Lord shall dwell unto the end."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Why suspect, ye curdled mountains?...Why do you suppose or imagine there may be any other such curdled mountains? You are mistaken: the mountain thus favoured by God is but one; and this same he has chosen for his dwelling for ever."})}),"\n",(0,s.jsx)(o,{verse:18,children:"The chariot of God is attended by ten thousands; thousands of them that rejoice: the Lord is among them in Sina, in the holy place."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: The chariot of God...Descending to give his law on mount Sina: as also of Jesus Christ his Son, ascending into heaven, to send from thence the Holy Ghost, to publish his new law, is attended with ten thousands, that is, with an innumerable multitude of joyful angels."})}),"\n",(0,s.jsx)(o,{verse:19,children:"Thou hast ascended on high, thou hast led captivity captive; thou hast received gifts in men. Yea for those also that do not believe, the dwelling of the Lord God."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Led captivity captive...Carrying away with thee to heaven those who before had been the captives of Satan; and receiving from God the Father gifts to be distributed to men; even to those who were before unbelievers."})}),"\n",(0,s.jsx)(o,{verse:20,children:"Blessed be the Lord day by day: the God of our salvation will make our journey prosperous to us."}),"\n",(0,s.jsx)(o,{verse:21,children:"Our God is the God of salvation: and of the Lord, of the Lord are the issues from death."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: The issues from death...The Lord alone is master of the issues, by which we may escape from death."})}),"\n",(0,s.jsx)(o,{verse:22,children:"But God shall break the heads of his enemies: the hairy crown of them that walk on in their sins."}),"\n",(0,s.jsx)(o,{verse:23,children:"The Lord said: I will turn them from Basan, I will turn them into the depth of the sea:"}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: I will turn them from Basan, etc...I will cast out my enemies from their rich possessions, signified by Basan, a fruitful country; and I will drive them into the depth of the sea: and make such a slaughter of them, that the feet of my servants may be dyed in their blood, etc."})}),"\n",(0,s.jsx)(o,{verse:24,children:"That thy foot may be dipped in the blood of thy enemies; the tongue of thy dogs be red with the same."}),"\n",(0,s.jsx)(o,{verse:25,children:"They have seen thy goings, O God, the goings of my God: of my king who is in his sanctuary."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Thy goings...Thy ways, thy proceedings, by which thou didst formerly take possession of the promised land in favour of thy people; and shalt afterwards of the whole world, which thou shalt subdue to thy Son."})}),"\n",(0,s.jsx)(o,{verse:26,children:"Princes went before joined with singers, in the midst of young damsels playing on timbrels."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Princes...The apostles, the first converters of nations; attended by numbers of perfect souls, singing the divine praises, and virgins consecrated to God."})}),"\n",(0,s.jsx)(o,{verse:27,children:"In the churches bless ye God the Lord, from the fountains of Israel."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: From the fountains of Israel...From whom both Christ and his apostles sprung. By Benjamin, the holy fathers on this place understand St. Paul, who was of that tribe, named here a youth, because he was the last called to the apostleship. By the princes of Juda, Zabulon, and Nephthali, we may understand the other apostles, who were of the tribe of Juda; or of the tribes of Zabulon, and Nephthali, where our Lord began to preach, Matt. 4.13, etc."})}),"\n",(0,s.jsx)(o,{verse:28,children:"There is Benjamin a youth, in ecstasy of mind. The princes of Juda are their leaders: the princes of Zabulon, the princes of Nephthali."}),"\n",(0,s.jsx)(o,{verse:29,children:"Command thy strength, O God confirm, O God, what thou hast wrought in us."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Command thy strength...Give orders that thy strength may be always with us."})}),"\n",(0,s.jsx)(o,{verse:30,children:"From thy temple in Jerusalem, kings shall offer presents to thee."}),"\n",(0,s.jsx)(o,{verse:31,children:"Rebuke the wild beasts of the reeds, the congregation of bulls with the kine of the people; who seek to exclude them who are tried with silver. Scatter thou the nations that delight in wars:"}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Rebuke the wild beasts of the reeds...or the wild beasts, which lie hid in the reeds. That is, the devils, who hide themselves in order to surprise their prey. Or by wild beasts, are here understood persecutors, who, for all their attempts against the Church, are but as weak reeds, which cannot prevail against them who are supported by the strength of the Almighty. The same are also called the congregation of bulls (from their rage against the Church) who assemble together all their kine, that is, the people their subjects, to exclude if they can, from Christ and his inheritance, his constant confessors, who are like silver tried by fire."})}),"\n",(0,s.jsx)(o,{verse:32,children:"Ambassadors shall come out of Egypt: Ethiopia shall soon stretch out her hands to God."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Ambassadors shall come, etc...It is a prophecy of the conversion of the Gentiles, and by name of the Egyptians and Ethiopians."})}),"\n",(0,s.jsx)(o,{verse:33,children:"Sing to God, ye kingdoms of the earth: sing ye to the Lord: Sing ye to God,"}),"\n",(0,s.jsx)(o,{verse:34,children:"Who mounteth above the heaven of heavens, to the east. Behold he will give to his voice the voice of power:"}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: To the east...From mount Olivet, which is on the east side of\nNote 2: Jerusalem.--Ibid. The voice of power...That is, he will make his voice to be a powerful voice: by calling from death to life, such as were dead in mortal sin: as at the last day he will by the power of his voice call all the dead from their graves."})}),"\n",(0,s.jsx)(o,{verse:35,children:"Give ye glory to God for Israel, his magnificence, and his power is in the clouds."}),"\n",(0,s.jsx)(o,{verse:36,children:"God is wonderful in his saints: the God of Israel is he who will give power and strength to his people. Blessed be God."})]})}function c(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},71184:(e,t,o)=>{o.d(t,{R:()=>h,x:()=>a});var s=o(14041);const n={},i=s.createContext(n);function h(e){const t=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:h(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);